function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<string>;
  var currentGroup := new StringBuilder;
  var groups := new List<string>;
  var ignoreSpace := True;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];

    if ignoreSpace and ch = ' ' then
      continue;

    if ch = '(' then
    begin
      if currentGroup.Length > 0 then
        stack.Push(currentGroup.ToString);
      currentGroup.Clear;
    end
    else if ch = ')' then
    begin
      currentGroup.Append(ch);
      currentGroup.Append(stack.Pop);
      groups.Add(currentGroup.ToString);
      currentGroup.Clear;
    end
    else
      currentGroup.Append(ch);
  end;

  Result := groups.ToArray;
end;


