function ParseNestedParens(parenString: string): array of integer;
begin
  var stack := new Stack<integer>;
  var parenLevel := 0;
  var parenIndex := 0;
  var parenResult := new List<integer>;
  var parenCharList := parenString.ToCharArray;

  for var i := 1 to parenCharList.Length do
  begin
    if parenCharList[i] = '(' then
    begin
      stack.Push(parenLevel);
      parenLevel += 1;
    end
    else if parenCharList[i] = ')' then
    begin
      parenLevel -= 1;
      if stack.Count > 0 then
      begin
        parenIndex := i;
        while (stack.Count > 0) and (stack.Peek <= parenLevel) do
        begin
          stack.Pop;
          if stack.Count > 0 then
            parenIndex := stack.Peek;
        end;
        parenResult.Add(parenIndex);
      end;
    end;
  end;

  Result := parenResult.ToArray;
end;


