function Factorize(n: integer): array of integer;
begin
  var factors := new List<integer>;
  var num := n;
  var i := 2;

  while i * i <= num do
  begin
    if num mod i = 0 then
    begin
      num := num div i;
      if not factors.Contains(i) then
        factors.Add(i);
    end
    else
      i += 1;
  end;

  if (num > 1) and (not factors.Contains(num)) then
    factors.Add(num);

  Result := factors.ToArray;
end;


