function PrimeFib(n: integer): integer;
begin
  var fib := new List<integer>;
  fib.Add(0);
  fib.Add(1);
  var prime := new List<integer>;
  prime.Add(2);

  var i := 3;
  while prime.Count < n do
  begin
    if (fib[i-1] + fib[i-2]) mod 2 = 0 then
    begin
      prime.Add(i);
      fib.Add(fib[i-1] + fib[i-2]);
    end;
    i += 1;
  end;

  Result := fib[n-1];
end;


function TriplesSumToZero(l: array of integer): boolean;
begin
  var sorted := l.ToArray;
  sorted.Sort;

  for var i := 0 to sorted.Length - 3 do
  begin
    if (i > 0) and (sorted[i] = sorted[i - 1]) then
      continue;

    var left := i + 1;
    var right := sorted.Length - 1;

    while left < right do
    begin
      var sum := sorted[i] + sorted[left] + sorted[right];
      if sum = 0 then
      begin
        Result := True;
        exit;
      end
      else if sum < 0 then
        left += 1
      else if sum > 0 then
        right -= 1
      else
      begin
        Result := True;
        exit;
      end;
    end;
  end;

  Result := False;
end;

