function SameChars(s0, s1: string): boolean;
begin
  var c0 := new Dictionary<char, integer>;
  var c1 := new Dictionary<char, integer>;

  foreach var ch in s0 do
    if c0.ContainsKey(ch) then
      c0[ch] += 1
    else
      c0[ch] := 1;

  foreach var ch in s1 do
    if c1.ContainsKey(ch) then
      c1[ch] += 1
    else
      c1[ch] := 1;

  Result := c0.Count = c1.Count;

  if not Result then
    exit(False);

  foreach var kv in c0 do
  begin
    var ch := kv.Key;
    if not c1.ContainsKey(ch) or (c1[ch] <> kv.Value) then
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;


