  var seen := new HashSet<integer>;

  while (i < l1.Length) and (j < l2.Length) do
  begin
    if l1[i] = l2[j] then
    begin
      if not seen.Contains(l1[i]) then
      begin
        common.Add(l1[i]);
        seen.Add(l1[i]);
      end;
      i += 1;
      j += 1;
    end
    else if l1[i] < l2[j] then
      i += 1
    else
      j += 1;
  end;

  Result := common.ToArray;
end;


