function IsMultiplyPrime(a: integer): boolean;
begin
  var primes := new List<integer>;

  for var num := 2 to a - 1 do
  begin
    var isPrime := True;
    for var i := 2 to Trunc(Sqrt(num)) do
      if num mod i = 0 then
      begin
        isPrime := False;
        break;
      end;

    if isPrime and (num <> 1) then
      primes.Add(num);
  end;

  var primeCount := primes.Count;

  if primeCount < 3 then
  begin
    Result := False;
    exit;
  end;

  var (a1, a2) := (primes[0], primes[1]);
  var (b1, b2) := (a1 * a2, a1 * a1);
  var (c1, c2) := (a2 * a2, a2 * a1);

  var (i1, i2) := (0, 1);
  var (j1, j2) := (0, 1);

  while (i1 < primeCount) and (j1 < primeCount) do
  begin
    if (i2 < primeCount) and (primes[i2] * primes[i2] = a1) and (primes[i2] * primes[i2] = a2) then
    begin
      i2 += 1;
      j2 += 1;
    end
    else if (j2 < primeCount) and (primes[j2] * primes[j2] = b1) and (primes[j2] * primes[j2] = b2) then
    begin
      j2 += 1;
    end
    else if (c2 = a1) and (c2 = a2) then
    begin
      i2 += 1;
      j2 += 1;
      c1 := primes[i2] * primes[i2];
      c2 := primes[j2] * primes[j2];
    end
    else
    begin
      i2 += 1;
      c1 := primes[i2] * primes[i2];
    end;

    if (c1 = a1) and (c1 = a2) then
    begin
      Result := True;
      exit;
    end;
  end;

  Result := False;
end;

begin
end.




