function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var rows := grid.Length;
  var cols := grid[0].Length;
  var buckets := new integer[rows, cols];
  var moves := 0;

  // Count the number of water wells
  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
      if grid[i][j] = 1 then
        buckets[i, j] := 1
      else
        buckets[i, j] := 0;

  // Empty the wells
  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
    begin
      if buckets[i, j] = 1 then
      begin
        // Check adjacent wells
        if (i > 0) and (buckets[i-1, j] = 0) then
          buckets[i-1, j] := 1;
        if (j > 0) and (buckets[i, j-1] = 0) then
          buckets[i, j-1] := 1;
        if (i < rows - 1) and (buckets[i+1, j] = 0) then
          buckets[i+1, j] := 1;
        if (j < cols - 1) and (buckets[i, j+1] = 0) then
          buckets[i, j+1] := 1;
        moves += 1;
      end;
    end;

  Result := moves;
end;

