  var closestVowel := '';

  while left < right - 1 do
  begin
    var mid := (left + right) div 2;
    if vowels.Contains(word[mid + 1]) then
    begin
      closestVowel := word[mid + 1];
      left := mid;
    end
    else if vowels.Contains(word[mid]) then
    begin
      closestVowel := word[mid];
      right := mid;
    end;
  end;

  if vowels.Contains(word[0]) then
    Result := word[0]
  else if vowels.Contains(word[word.Length - 1]) then
    Result := word[word.Length - 1]
  else
    Result := '';
