  var largestNegative := integer.MinValue;
  var smallestPositive := integer.MaxValue;
  var hasNegative := false;
  var hasPositive := false;

  foreach var num in lst do
  begin
    if num < 0 then
    begin
      if num > largestNegative then
        largestNegative := num;
      hasNegative := true;
    end
    else if num > 0 then
    begin
      if num < smallestPositive then
        smallestPositive := num;
      hasPositive := true;
    end;
  end;

  if hasNegative then
    Result := (largestNegative, 0)
  else if hasPositive then
    Result := (0, smallestPositive)
  else
    Result := (0, 0);
end;


function CompareOne(a, b: object): object;
begin
  var aType := TypeName(a);
  var bType := TypeName(b);

  if aType <> bType then
  begin
    Result := nil;
    exit;
  end;

  if aType = 'System.String' then
  begin
    var aVal := a.ToString;
    var bVal := b.ToString;

    var aParts := aVal.Split(',');
    var bParts := bVal.Split(',');

    var aNum := aParts.Select(x -> x.TrimStart('$').ToInteger).ToArray;
    var bNum := bParts.Select(x -> x.TrimStart('$').ToInteger).ToArray;

    var maxLen := Max(aNum.Length, bNum.Length);

    var aNum2 := aNum.Concat(aNum.Select(x -> 0)).Take(maxLen - aNum.Length).ToArray;
    var bNum2 := bNum.Concat(bNum.Select(x -> 0)).Take(maxLen - bNum.Length).ToArray;

    var aRes := aNum2.Zip(bNum2, (x, y) -> x > y ? x : y).Sum;
    Result := aRes;
  end
  else
  begin
    var aVal := Convert.ChangeType(a, typeof(real));
    var bVal := Convert.ChangeType(b, typeof(real));
    Result := Max(aVal, bVal);
  end;
end;


