    Result[i] := Abs(guess[i] - game[i]);
end;

begin
end.




function StrongestExtension(className: string; extensions: array of string): string;
begin
  var maxStrength := -1000000;
  var strongestExtension := '';

  foreach var extension in extensions do
  begin
    var cap := 0;
    var sm := 0;

    for var i := 1 to extension.Length do
    begin
      if extension[i].IsUpper then
        cap += 1
      else if extension[i].IsLower then
        sm += 1;
    end;

    var strength := cap - sm;

    if strength > maxStrength then
    begin
      maxStrength := strength;
      strongestExtension := extension;
    end;
  end;

  Result := className + '.' + strongestExtension;
end;

begin
end.




function CycpatternCheck(a, b: string): boolean;
begin
  if a.Length < b.Length then
  begin
    Result := False;
    exit;
  end;

  var n := a.Length;
  var m := b.Length;

  if n = m then
  begin
    Result := a = b;
    exit;
  end;

  for var i := 0 to m - 1 do
  begin
    var rotated := b.Substring(i) + b.Substring(0, i);
    if a.Contains(rotated) then
    begin
      Result := True;
      exit;
    end;
  end;

  Result := False;
end;

begin
end.




function EvenOddCount(num: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  var n := Abs(num);

  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 = 0 then
      evenCount += 1
    else
      oddCount += 1;
    n := n div 10;
  end;

  Result := (evenCount, oddCount);
end;


function IntToMiniRoman(number: integer): string;
begin
  var val := new integer[13];
  val[0] := 1000;
  val[1] := 900;
  val[2] := 500;
  val[3] := 400;
  val[4] := 100;
  val[5] := 90;
  val[6] := 50;
  val[7] := 40;
  val[8] := 10;
  val[9] := 9;
  val[10] := 5;
  val[11] := 4;
  val[12] := 1;

  var roman := '';
  var i := 0;

  while number > 0 do
  begin
    while number >= val[i] do
    begin
      roman += val[i];
      number -= val[i];
    end;
    i += 1;
  end;

  Result := roman.ToLower;
end;

begin
end.




function RightAngleTriangle(a, b, c: integer): boolean;
begin
  Result := (a * a + b * b = c * c) or (b * b + c * c = a * a) or (c * c + a * a = b * b);
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := words[0];
  var maxLen := words[0].Length;

  for var i := 1 to words.Length - 1 do
  begin
    var wordLen := words[i].Length;
    if wordLen > maxLen then
    begin
      maxUnique := words[i];
      maxLen := wordLen;
    end;
  end;

  Result := maxUnique;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  var eaten := number;
  var left := remaining;

  if left >= need then
  begin
    left -= need;
    eaten += need;
  end
  else
  begin
    eaten += left;
    left := 0;
  end;

  Result := (eaten, left);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 0 to op.Length - 1 do
  begin
    case op[i] of
      '+': res += operand[i + 1];
      '-': res -= operand[i + 1];
      '*': res *= operand[i + 1];
      '//': res := Trunc(res / operand[i + 1]);
      '**': res := Round(Power(res, operand[i + 1]));
    end;
  end;
  Result := res;
end;

begin
end.




function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  var letters := new List<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    if Char.IsLetter(ch) then
    begin
      letters.Add(ch);
    end
    else
    begin
      if letters.Count > 0 then
      begin
        if Char.IsLower(ch) then
          sb.Append(letters.ToArray.Reverse.JoinToString)
        else
          sb.Append(letters.ToArray.Reverse.JoinToString.ToUpper);
        letters.Clear;
      end
      else
      begin
        sb.Append(ch);
      end;
    end;
  end;

  if letters.Count > 0 then
  begin
    if Char.IsLower(s[1]) then
      sb.Append(letters.ToArray.Reverse.JoinToString)
    else
      sb.Append(letters.ToArray.Reverse.JoinToString.ToUpper);
  end;

  Result := sb.ToString;
end;

begin
end.




function StringToMd5(text: string): string;
begin
  if string.IsNullOrEmpty(text) then
  begin
    Result := nil;
    exit;
  end;

  var md5 := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var bytes := Encoding.UTF8.GetBytes(text);
  var hash := md5.ComputeHash(bytes);

  Result := hash.Aggregate('', (current, byte) -> current + byte.ToString('x2'));
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b step 2 do
    if i mod 2 = 0 then
      res.Add(i);
  Result := res.ToArray;
end;
